    const meta = buildTelemetry(ev);
    const denyHit = Object.keys(ev).filter(k => TELEMETRY_DENY.test(k));
    if (denyHit.length) {
        console.error('telemetry: refused event, denied fields: ' + denyHit.join(','));
        return;
    }
